912:   return p.lapsCompleted + (p.lapsCompleted === 0 && s > 0.72 ? s - 1 : s);
913: }
914: 
915: function getStandings() {
916:   const p = race.player;
917:   const playerP = playerProgress();
918:   const rows = [{
919:     name: 'YOU', color: '#ff4d1f', progress: playerP,
920:     isPlayer: true, lap: Math.min(TOTAL_LAPS, p.lapsCompleted + 1), finished: p.finished
921:   }];
922:   for (const a of race.ai) {
923:     const prog = a.dist / race.track.length;
924:     rows.push({
925:       name: a.name, color: a.color, progress: prog,
926:       isPlayer: false, lap: clamp(Math.floor(a.dist / race.track.length) + 1, 1, TOTAL_LAPS),
927:       finished: a.finished
928:     });
929:   }
930:   rows.sort((a, b) => b.progress - a.progress);
931:   return rows;
932: }
