934: /* ═══════════════════════════════════════════════════════════════════
935:    Player physics
936:    ═══════════════════════════════════════════════════════════════════ */
937: const DUST_COLOR = new THREE.Color(0xc9b28a);
938: const SMOKE_COLOR = new THREE.Color(0xdad7d0);
939: let emitAccum = 0;
940: let minimapFrame = 0;
941: 
942: // Arcade-first handling. The car turns in almost immediately, carries more
943: // cornering force than a real F1 car, and bleeds off sideways slide quickly so
944: // the nose goes where you point it instead of washing wide into the scenery.
945: const HANDLING = {
946:   steerLowSpeed: 0.60,   // max steering angle at a crawl (rad)
947:   steerHighSpeed: 0.19,  // max steering angle at speed (rad)
948:   steerSpeedRef: 58,
949:   steerResponse: 18,     // how fast your input reaches the wheels
950:   yawResponse: 15,       // how fast the chassis follows the wheels
951:   gripTrack: 46,         // lateral acceleration budget on asphalt (m/s²)
952:   gripKerb: 38,
953:   gripOffroad: 27,
954:   gripHandbrake: 19,
955:   sideGripTrack: 12.5,   // how quickly sideways velocity is killed
956:   sideGripKerb: 11,
957:   sideGripOffroad: 5.5,
958:   sideGripHandbrake: 2.1,
959:   offroadPower: 0.55,    // engine output on grass, so you can drive back
960:   offroadDrag: 5.5
961: };
962: 
963: // The car drives its own throttle and brakes. The player owns the steering;
964: // W/S are always available as a direct override for extra speed or stopping.
965: const AUTODRIVE = {
966:   lateral: 31,        // cornering budget used to plan safe corner speeds (m/s²)
967:   brakeDecel: 24,     // braking force assumed when looking ahead (m/s²)
968:   maxSpeed: 84,       // cruise ceiling in m/s (≈302 km/h)
969:   offroadMax: 30,     // don't keep charging across the grass
970:   minSpeed: 20,
971:   cruiseThrottle: 0.4 // throttle that balances drag near the target speed
972: };
973: 
974: function autoDriveDemand(p, track) {
975:   const N = track.N;
976:   const base = Math.floor((((p.sNorm % 1) + 1) % 1) * N) % N;
977:   const speed = Math.max(0, p.vLong);
978:   const lookAhead = clamp(55 + speed * 1.55, 55, 190);
979:   const stride = Math.max(1, Math.round(5 / track.step));
980:   const maxSteps = Math.round(lookAhead / track.step);
981:   let target = AUTODRIVE.maxSpeed;
982: 
983:   // Scan the road ahead and find the fastest speed we can still brake down to
984:   // every upcoming corner from. This does the "when do I lift?" thinking.
985:   for (let d = 0; d <= maxSteps; d += stride) {
986:     const s = track.samples[(base + d) % N];
987:     const radius = Math.max(1 / Math.max(Math.abs(s.k), 1e-5), 24);
988:     const corner = Math.sqrt(AUTODRIVE.lateral * radius);
989:     const dist = d * track.step;
990:     target = Math.min(target, Math.sqrt(corner * corner + 2 * AUTODRIVE.brakeDecel * dist));
991:   }
992:   if (p.offroad) target = Math.min(target, AUTODRIVE.offroadMax);
993:   target = clamp(target, AUTODRIVE.minSpeed, AUTODRIVE.maxSpeed);
994: 
995:   const gap = target - speed;
996:   const throttle = clamp(AUTODRIVE.cruiseThrottle + gap * 0.55, 0, 1);
997:   const brake = speed > target + 0.8
998:     ? clamp((speed - target - 0.8) / 5, 0.12, 1)
999:     : 0;
1000:   return { throttle, brake, target };
1001: }
1002: 
1003: function readControls() {
1004:   const active = race.state === 'racing';
1005:   return {
1006:     active,
1007:     gas: active && (input.gas || input.touchGas),
1008:     brake: active && (input.brake || input.touchBrake),
1009:     steer: active ? ((input.left || input.touchLeft ? 1 : 0) - (input.right || input.touchRight ? 1 : 0)) : 0,
1010:     handbrake: active && input.handbrake
1011:   };
1012: }
1013: 
1014: function updatePlayerPhysics(dt) {
1015:   const p = race.player;
1016:   const tr = race.track;
1017:   const controls = readControls();
1018:   const manualGas = controls.gas;
1019:   const manualBrake = controls.brake;
1020:   const handbrake = controls.handbrake;
1021: 
1022:   let throttleDemand = 0;
1023:   let brakeDemand = 0;
1024:   let assistState = 'auto';
1025: 
1026:   if (controls.active) {
1027:     if (manualBrake) {
1028:       // Player brake always wins — it is stronger than the auto brake.
1029:       brakeDemand = 1;
1030:       assistState = 'manual';
1031:     } else if (manualGas) {
1032:       // Player throttle overrides the speed planner so you can chase a faster lap.
1033:       throttleDemand = 1;
1034:       assistState = 'manual';
1035:     } else if (!handbrake) {
1036:       const auto = autoDriveDemand(p, race.track);
1037:       throttleDemand = auto.throttle;
1038:       brakeDemand = auto.brake;
1039:       assistState = auto.brake > 0.15 ? 'auto-brake' : 'auto';
1040:     } else {
1041:       assistState = 'manual';
1042:     }
1043:   }
1044:   p.assistState = assistState;
1045: 
1046:   p.throttle = damp(p.throttle, throttleDemand, 11, dt);
1047:   p.brake = damp(p.brake, brakeDemand, 16, dt);
1048:   p.steer = damp(p.steer, controls.steer, HANDLING.steerResponse, dt);
1049: 
1050:   const speed0 = Math.hypot(p.vel.x, p.vel.z);
1051:   const f0x = Math.sin(p.yaw), f0z = Math.cos(p.yaw);
1052:   const vLong0 = p.vel.x * f0x + p.vel.z * f0z;
1053: 
1054:   const maxSteer = lerp(
1055:     HANDLING.steerLowSpeed,
1056:     HANDLING.steerHighSpeed,
1057:     clamp(speed0 / HANDLING.steerSpeedRef, 0, 1)
1058:   );
1059:   const steerAngle = p.steer * maxSteer;
1060:   const gripAccel = p.offroad
1061:     ? HANDLING.gripOffroad
1062:     : handbrake
1063:       ? HANDLING.gripHandbrake
1064:       : p.onKerb
1065:         ? HANDLING.gripKerb
1066:         : HANDLING.gripTrack;
1067:   const maxYaw = gripAccel / Math.max(4, speed0);
1068:   let yawTarget = (vLong0 / 3.05) * Math.tan(steerAngle);
1069:   if (handbrake) yawTarget *= 1.55;
1070:   yawTarget = clamp(yawTarget, -maxYaw, maxYaw);
1071:   p.yawRate = damp(p.yawRate, yawTarget, HANDLING.yawResponse, dt);
1072:   p.yaw += p.yawRate * dt;
1073:   p.yaw = ((p.yaw + Math.PI) % TAU + TAU) % TAU - Math.PI;
1074: 
1075:   const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1076:   const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1077: 
1078:   let vLong = p.vel.x * fx + p.vel.z * fz;
1079:   let vLat = p.vel.x * rx + p.vel.z * rz;
1080: 
1081:   const drs = race.state === 'racing' && vLong > 55 && Math.abs(p.lastK || 0) < 1 / 420 && p.throttle > 0.35;
1082:   p.drs = drs;
1083: 
1084:   let accel = 0;
1085:   if (p.throttle > 0.01) {
1086:     const maxSpeed = drs ? 96 : 90;
1087:     const ratio = clamp(vLong / maxSpeed, -1, 1);
1088:     const engine = 18.5 * Math.max(0, 1 - ratio * ratio);
1089:     accel += engine * p.throttle * (p.offroad ? HANDLING.offroadPower : 1);
1090:   }
1091:   if (p.brake > 0.01) {
1092:     if (vLong > 0.35) accel -= 33 * p.brake;
1093:     else accel -= 6.8 * p.brake;
1094:   }
1095:   if (handbrake) accel -= 9;
1096:   const dragCoef = drs ? 0.000165 : 0.00022;
1097:   const drag = dragCoef * vLong * Math.abs(vLong) + 0.6 * Math.sign(vLong) + (p.offroad ? HANDLING.offroadDrag : 0);
1098:   accel -= drag;
1099:   vLong += accel * dt;
1100:   if (vLong < -12) vLong = -12;
1101:   if (p.throttle < 0.02 && p.brake < 0.02 && !handbrake && Math.abs(vLong) < 0.2) vLong = 0;
1102: 
1103:   const sideGrip = p.offroad
1104:     ? HANDLING.sideGripOffroad
1105:     : handbrake
1106:       ? HANDLING.sideGripHandbrake
1107:       : p.onKerb
1108:         ? HANDLING.sideGripKerb
1109:         : HANDLING.sideGripTrack;
1110:   vLat *= Math.exp(-sideGrip * dt);
1111: 
1112:   p.vLong = vLong;
1113:   p.vLat = vLat;
1114:   p.vel.x = fx * vLong + rx * vLat;
1115:   p.vel.z = fz * vLong + rz * vLat;
1116:   p.pos.x += p.vel.x * dt;
1117:   p.pos.z += p.vel.z * dt;
1118: 
1119:   const near = race.locator.nearest(p.pos.x, p.pos.z);
1120:   const sample = tr.samples[near.index];
1121:   p.sNorm = (near.index % tr.N) / tr.N;
1122:   p.trackDist = near.dist;
1123:   p.lastK = sample.k;
1124:   p.offroad = near.dist > tr.halfWidth + 1.15;
1125:   p.onKerb = !p.offroad && near.dist > tr.halfWidth - 0.55 && near.dist < tr.halfWidth + 1.6;
1126:   if (p.offroad) {
1127:     p.offTimer += dt * (near.dist > tr.halfWidth + 25 ? 2 : 1);
1128:   } else {
1129:     p.offTimer = Math.max(0, p.offTimer - dt * 2.5);
1130:   }
1131:   if (race.state === 'racing' && p.offTimer > 2.7) recoverPlayer();
1132: 
1133:   const kmh = Math.abs(vLong) * 3.6;
1134:   if (race.state === 'racing') p.topSpeed = Math.max(p.topSpeed, kmh);
1135: }
1136: 
1137: function updatePlayerVisual(dt) {
1138:   const p = race.player;
1139:   const car = race.playerCar;
1140:   car.root.position.set(p.pos.x, 0, p.pos.z);
1141:   car.root.rotation.y = p.yaw;
1142: 
1143:   const longAccel = (p.vLong - p.prevVLong) / Math.max(dt, 0.001);
1144:   p.prevVLong = p.vLong;
1145:   car.body.rotation.x = damp(car.body.rotation.x, clamp(-longAccel * 0.0022, -0.055, 0.055), 7, dt);
1146:   car.body.rotation.z = damp(car.body.rotation.z, clamp(p.vLong * p.yawRate * 0.0032, -0.07, 0.07), 7, dt);
1147: 
1148:   const steerVisual = p.steer * lerp(
1149:     HANDLING.steerLowSpeed * 0.82,
1150:     HANDLING.steerHighSpeed * 1.2,
1151:     clamp(Math.abs(p.vLong) / HANDLING.steerSpeedRef, 0, 1)
1152:   );
1153:   for (const w of car.wheels) {
1154:     w.spin.rotation.x += (p.vLong / w.radius) * dt;
1155:     if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, steerVisual, 18, dt);
1156:   }
1157:   car.setBrake(p.brake > 0.08 || race.state === 'finished');
1158:   car.setDRS(p.drs);
1159: 
1160:   // tyre smoke and grass dust
1161:   const slip = Math.abs(p.vLat);
1162:   const speed = Math.abs(p.vLong);
1163:   const rate = p.offroad && speed > 4 ? 42 : (slip > 2.4 && speed > 6 ? 26 : 0);
1164:   if (rate && race.state !== 'countdown') {
1165:     emitAccum += dt * rate;
1166:     while (emitAccum >= 1) {
1167:       emitAccum -= 1;
1168:       const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1169:       const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1170:       const side = Math.random() > 0.5 ? 1 : -1;
1171:       const x = p.pos.x - fx * 1.65 + rx * side * 0.85;
1172:       const z = p.pos.z - fz * 1.65 + rz * side * 0.85;
1173:       const color = p.offroad ? DUST_COLOR : SMOKE_COLOR;
1174:       race.smoke.emit(x, 0.22, z, color, p.offroad ? 0.9 : 0.7, p.offroad ? 1.25 : 1.0, p.offroad ? 2.4 : 1.6);
1175:     }
1176:   }
1177: }
1178: 
1179: function recoverPlayer(showToast = true) {
1180:   const p = race.player;
1181:   const near = race.locator.nearest(p.pos.x, p.pos.z);
1182:   const s = race.track.samples[near.index];
1183:   p.pos = { x: s.x, z: s.z };
1184:   p.vel = { x: 0, z: 0 };
1185:   p.vLong = 0; p.vLat = 0;
1186:   p.yaw = Math.atan2(s.tx, s.tz);
1187:   p.offroad = false;
1188:   p.offTimer = 0;
1189:   p.sNorm = (near.index % race.track.N) / race.track.N;
1190:   p.prevS = p.sNorm;
1191:   race.locator.lastIndex = near.index;
1192:   // Cut the camera with the car rather than letting it swoop across the
1193:   // circuit to the recovery point.
1194:   race.camYaw = p.yaw;
1195:   race.cameraReady = false;
1196:   race.camLook.set(s.x + Math.sin(p.yaw) * 7, 0.92, s.z + Math.cos(p.yaw) * 7);
1197:   race.smoke.reset();
1198:   if (showToast) {
1199:     toast('Recovered to the racing line');
1200:     audio.tone(330, 0.1, 0.04, 'triangle');
1201:   }
1202: }
