1204: /* ═══════════════════════════════════════════════════════════════════
1205:    Lap logic
1206:    ═══════════════════════════════════════════════════════════════════ */
1207: function completeLap() {
1208:   const p = race.player;
1209:   const lapTime = race.time - p.lapStart;
1210:   if (lapTime > 3000) {
1211:     p.lastLap = lapTime;
1212:     if (!p.bestLap || lapTime < p.bestLap) {
1213:       p.bestLap = lapTime;
1214:       writeBest(race.track.seed, lapTime);
1215:       toast(`NEW BEST LAP · ${formatTime(lapTime)}`);
1216:     }
1217:   }
1218:   p.lapsCompleted++;
1219:   p.lapStart = race.time;
1220:   p.sectors = [false, false, false];
1221:   if (p.lapsCompleted >= TOTAL_LAPS) {
1222:     finishRace();
1223:   } else if (p.lapsCompleted === TOTAL_LAPS - 1) {
1224:     showRaceMessage('FINAL LAP', 'EVERYTHING YOU HAVE', 2300, true);
1225:     audio.tone(880, 0.18, 0.06, 'triangle');
1226:   } else {
1227:     showRaceMessage(`LAP ${p.lapsCompleted + 1} / ${TOTAL_LAPS}`, 'KEEP IT CLEAN', 1900);
1228:     audio.tone(660, 0.1, 0.04, 'triangle');
1229:   }
1230: }
1231: 
1232: function updatePlayerProgress(dt) {
1233:   const p = race.player;
1234:   if (p.finished) return;
1235:   const tr = race.track;
1236:   const near = race.locator.nearest(p.pos.x, p.pos.z);
1237:   const s = tr.samples[near.index];
1238:   const forwardDot = p.vel.x * s.tx + p.vel.z * s.tz;
1239:   const sNorm = (near.index % tr.N) / tr.N;
1240: 
1241:   if (forwardDot > 0.4 && sNorm < 0.9) {
1242:     if (sNorm > 0.13) p.sectors[0] = true;
1243:     if (sNorm > 0.38) p.sectors[1] = true;
1244:     if (sNorm > 0.64) p.sectors[2] = true;
1245:   }
1246: 
1247:   const crossed = p.prevS > 0.82 && sNorm < 0.18 && forwardDot > 0;
1248:   if (crossed) {
1249:     if (p.sectors[0] && p.sectors[1] && p.sectors[2]) completeLap();
1250:     else p.sectors = [false, false, false];
1251:   }
1252:   p.prevS = sNorm;
1253: }
1254: 
1255: /* ═══════════════════════════════════════════════════════════════════
1256:    AI drivers
1257:    ═══════════════════════════════════════════════════════════════════ */
1258: /* Cars are three overlapping circles rather than one big invisible circle, so
1259:    contact happens where the bodywork actually is. When you run into another
1260:    car you scrub speed and get nudged along it — the closing speed is killed,
1261:    never reflected, so you are not fired backwards like a rubber ball. */
1262: const CONTACT = {
1263:   offsets: [1.45, 0, -1.45],
1264:   radii: [1.02, 1.06, 1.02]
1265: };
1266: const SPARK_COLOR = new THREE.Color(0xffb257);
1267: const playerCircles = new Float32Array(6);
1268: const aiCircles = new Float32Array(6);
1269: let contactCooldown = 0;
1270: 
1271: function fillCarCircles(x, z, yaw, out) {
1272:   const fx = Math.sin(yaw);
1273:   const fz = Math.cos(yaw);
1274:   for (let i = 0; i < 3; i++) {
1275:     const o = CONTACT.offsets[i];
1276:     out[i * 2] = x + fx * o;
1277:     out[i * 2 + 1] = z + fz * o;
1278:   }
1279:   return out;
1280: }
1281: 
1282: function resolveCarCollisions(dt = 1 / 60) {
1283:   const p = race.player;
1284:   const tr = race.track;
1285:   if (contactCooldown > 0) contactCooldown = Math.max(0, contactCooldown - dt);
1286: 
1287:   fillCarCircles(p.pos.x, p.pos.z, p.yaw, playerCircles);
1288: 
1289:   for (const a of race.ai) {
1290:     const ax = a.model.root.position.x;
1291:     const az = a.model.root.position.z;
1292:     const ayaw = a.model.root.rotation.y;
1293:     fillCarCircles(ax, az, ayaw, aiCircles);
1294: 
1295:     let overlap = 0;
1296:     let nx = 0;
1297:     let nz = 0;
1298:     let contactX = 0;
1299:     let contactZ = 0;
1300:     for (let i = 0; i < 3; i++) {
1301:       const px = playerCircles[i * 2];
1302:       const pz = playerCircles[i * 2 + 1];
1303:       for (let j = 0; j < 3; j++) {
1304:         const cx = aiCircles[j * 2];
1305:         const cz = aiCircles[j * 2 + 1];
1306:         const dx = px - cx;
1307:         const dz = pz - cz;
1308:         const dist = Math.hypot(dx, dz) || 0.0001;
1309:         const deep = CONTACT.radii[i] + CONTACT.radii[j] - dist;
1310:         if (deep <= overlap) continue;
1311:         overlap = deep;
1312:         nx = dx / dist;
1313:         nz = dz / dist;
1314:         contactX = (px + cx) * 0.5;
1315:         contactZ = (pz + cz) * 0.5;
1316:       }
1317:     }
1318:     if (overlap <= 0) continue;
1319: 
1320:     const aFx = Math.sin(ayaw);
1321:     const aFz = Math.cos(ayaw);
1322:     const aRx = Math.cos(ayaw);
1323:     const aRz = -Math.sin(ayaw);
1324:     const aiVx = aFx * a.speed;
1325:     const aiVz = aFz * a.speed;
1326:     const relVx = p.vel.x - aiVx;
1327:     const relVz = p.vel.z - aiVz;
1328:     const vn = relVx * nx + relVz * nz;
1329: 
1330:     // Split the positional separation between the two cars. The player is
1331:     // shoved sideways off the other car; the AI takes the rest as a shove
1332:     // along the track, so you can lean on it and muscle past instead of
1333:     // bouncing back down the road.
1334:     const push = Math.min(overlap, 0.7);
1335:     p.pos.x += nx * push * 0.55;
1336:     p.pos.z += nz * push * 0.55;
1337: 
1338:     const s = sampleAtDistance(tr, a.dist);
1339:     const shove = push * 0.5;
1340:     a.dist += (s.tx * -nx + s.tz * -nz) * shove;
1341:     const latLimit = Math.max(2.4, tr.halfWidth - 1.6);
1342:     a.lateral = clamp(a.lateral + (s.nx * -nx + s.nz * -nz) * shove, -latLimit, latLimit);
1343: 
1344:     // Contact is always worth a small scrub and a side-step, even when the
1345:     // relative speed is tiny, so cars rub instead of sticking together.
1346:     const fx = Math.sin(p.yaw);
1347:     const fz = Math.cos(p.yaw);
1348:     const rx = Math.cos(p.yaw);
1349:     const rz = -Math.sin(p.yaw);
1350:     let impact = 0;
1351:     if (vn < 0) {
1352:       impact = Math.min(1, Math.abs(vn) / 26);
1353:       // Remove only the speed heading into the other car. Whatever speed you
1354:       // carry along the contact patch stays, so you keep driving forward.
1355:       p.vel.x -= nx * vn;
1356:       p.vel.z -= nz * vn;
1357:       const tanVx = relVx - nx * vn;
1358:       const tanVz = relVz - nz * vn;
1359:       const scrub = 0.07 + impact * 0.16;
1360:       p.vel.x -= tanVx * scrub;
1361:       p.vel.z -= tanVz * scrub;
1362: 
1363:       // How square-on the hit is: 1 = straight up the gearbox, 0 = pure
1364:       // side swipe. Square-on hits get a firm side-step so you peel around
1365:       // the car ahead instead of grinding along behind it.
1366:       const squareOn = Math.abs(nx * fx + nz * fz);
