if (action === 'tick') {
  await page.evaluate(async () => {
    window.__apex.startRaceNow();
    for (let i = 0; i < 60 * 25; i++) window.__apex.tick(1 / 60);
  });
  await page.waitForTimeout(600);
}

if (action === 'sim') {
  await page.evaluate(async () => {
    const apex = window.__apex;
    apex.startRaceNow();
    const race = apex.race;
    const tr = race.track;
    for (let i = 0; i < 60 * 45; i++) {
      const p = race.player;
      const near = race.locator.nearest(p.pos.x, p.pos.z);
      const look = tr.samples[(near.index + 26) % tr.N];
      const desiredYaw = Math.atan2(look.x - p.pos.x, look.z - p.pos.z);
      let diff = desiredYaw - p.yaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      apex.setDemoInput({ left: diff > 0.025, right: diff < -0.025, gas: false, brake: false });
      apex.tick(1 / 60);
    }
    apex.setDemoInput({ left: false, right: false });
  });
  await page.waitForTimeout(600);
}

